toolSchema:
{
  "title": "WeatherTool.getWeather",
  "description": "Look up a weather forecast.",
  "type": "object",
  "properties": {
    "days": {
      "type": "number",
      "minimum": 1,
      "maximum": 7
    },
    "location": {
      "description": "the city to look up",
      "type": "string",
      "minLength": 1
    },
    "unit": {
      "type": "string",
      "enum": [
        "celsius",
        "fahrenheit"
      ]
    }
  },
  "required": [
    "location",
    "unit",
    "days"
  ],
  "additionalProperties": false
}
